"""Inspect budget.xlsx and calculate total expenses across all categories."""
import json
import sys
from pathlib import Path

import openpyxl

FILE = "budget.xlsx"


def cell_value(cell):
    v = cell.value
    if v is None:
        return None
    if isinstance(v, str):
        return v.strip()
    return v


def main():
    if not Path(FILE).exists():
        print(json.dumps({"status": "error", "message": f"{FILE} not found"}))
        return 1

