    report = {"file": FILE, "sheets": []}

    for ws in wb.worksheets:
        rows = list(ws.iter_rows())
        if not rows:
            report["sheets"].append({"name": ws.title, "rows": 0, "note": "empty"})
            continue

        header = [cell_value(c) for c in rows[0]]
        report["sheets"].append(
            {
                "name": ws.title,
                "rows": len(rows),
                "header": header,
                "preview": [
                    [cell_value(c) for c in row]
                    for row in rows[1:6]
                ],
            }
        )
    print(json.dumps(report, indent=2, default=str))
    return 0


if __name__ == "__main__":
    sys.exit(main())

