"""Inspect budget.xlsx and calculate total expenses across all categories.

Parses the xlsx (zip of XML) with the standard library only.
"""
import json
import re
import sys
import zipfile
from pathlib import Path
from xml.etree import ElementTree as ET

FILE = "budget.xlsx"
NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}


def col_to_idx(ref):
    """'A'->1, 'AB'->28"""
    letters = re.match(r"([A-Z]+)", ref).group(1)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx


def parse_shared_strings(z):
    if "xl/sharedStrings.xml" not in z.namelist():
        return []
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    out = []
    for si in root.findall("m:si", NS):
        text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
        out.append(text)
    return out


def sheet_cells(z, sheet_path):
    root = ET.fromstring(z.read(sheet_path))
    cells = {}
    for c in root.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
        ref = c.get("r")
        if not ref:
            continue
        t = c.get("t")
        v = c.find("m:v", NS)
        if v is None or v.text is None:
            continue
        val = v.text
        if t == "s":
            val = shared[ int(val) ]
        elif t == "b":
            val = val == "1"
        elif t == "str":
            pass
        else:
            try:
                if re.fullmatch(r"-?\d+", val):
                    val = int(val)
                else:
                    val = float(val)
            except ValueError:
                pass
        cells[ref] = val
    return cells


def numeric(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def main():
    if not Path(FILE).exists():
        print(json.dumps({"status": "error", "message": f"{FILE} not found"}))
        return 1

    with zipfile.ZipFile(FILE) as z:
        global shared
        shared = parse_shared_strings(z)

        wb_root = ET.fromstring(z.read("xl/workbook.xml"))
        rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
        rel_map = {
            rel.get("Id"): rel.get("Target")
            for rel in rels_root.findall("{http://schemas.openxmlformats.org/package/2006/relationships}Relationship")
        }
        sheets = []
        for s in wb_root.find("m:sheets", NS):
            name = s.get("name")
            rid = s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
            target = rel_map.get(rid, "")
            if not target.startswith("xl/"):
                target = "xl/" + target.lstrip("/")
            sheets.append((name, target))

        report = {"file": FILE, "sheets": []}
        for name, target in sheets:
            cells = sheet_cells(z, target)
            rows = {}
            for ref, val in cells.items():
                r = int(re.match(r"[A-Z]+(\d+)", ref).group(1))
                c = col_to_idx(ref)
                rows.setdefault(r, {})[c] = val

            max_col = max((c for row in rows.values() for c in row), default=0)
            max_row = max(rows, default=0)
            grid = [[rows.get(r, {}).get(c) for c in range(1, max_col + 1)] for r in range(1, max_row + 1)]
            report["sheets"].append(
                {
                    "name": name,
                    "rows": max_row,
                    "cols": max_col,
                    "grid": grid,
                }
            )
    print(json.dumps(report, indent=2, default=str))
    return 0


if __name__ == "__main__":
    sys.exit(main())

