"""Calculate total expenses across all categories in budget.xlsx.

Uses the same stdlib xlsx parser, then sums the amounts of every expense
line item (the EXPENSES section between the 'EXPENSES' header row and the
'Total Expenses' label row).
"""
import json
import re
import sys
import zipfile
from pathlib import Path
from xml.etree import ElementTree as ET

FILE = "budget.xlsx"
M = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"


def col_to_idx(ref):
    letters = re.match(r"([A-Z]+)", ref).group(1)
    idx = 0
    for ch in letters:
