    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    out = []
    for si in root.iter(M + "si"):
        text = "".join(t.text or "" for t in si.iter(M + "t"))
        out.append(text)
    return out


def sheet_cells(z, sheet_path, shared):
    root = ET.fromstring(z.read(sheet_path))
    cells = {}
    for c in root.iter(M + "c"):
        ref = c.get("r")
        if not ref:
            continue
        t = c.get("t")
        v = c.find(M + "v")
        is_el = c.find(M + "is")
        val = None
        if t == "inlineStr" and is_el is not None:
            val = "".join(x.text or "" for x in is_el.iter(M + "t"))
        elif v is not None and v.text is not None:
            val = v.text
            if t == "s":
                val = shared[int(val)]
            elif t == "b":
                val = val == "1"
            else:
                try:
                    val = int(val) if re.fullmatch(r"-?\d+", val) else float(val)
                except ValueError:
                    pass
        cells[ref] = val
    return cells


def main():
    if not Path(FILE).exists():
        print(json.dumps({"status": "error", "message": f"{FILE} not found"}))
        return 1

    with zipfile.ZipFile(FILE) as z:
        shared = parse_shared_strings(z)
        wb_root = ET.fromstring(z.read("xl/workbook.xml"))
        rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
        rel_map = {
            rel.get("Id"): rel.get("Target")
            for rel in rels_root.findall("{http://schemas.openxmlformats.org/package/2006/relationships}Relationship")
        }
        s0 = wb_root.find("m:sheets", NS={"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"})[0]
        rid = s0.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")
        target = rel_map.get(rid, "")
        if target.startswith("/"):
            target = target.lstrip("/")
        elif not target.startswith("xl/"):
            target = "xl/" + target

        cells = sheet_cells(z, target, shared)
        rows = {}
        for ref, val in cells.items():
            r = int(re.match(r"[A-Z]+(\d+)", ref).group(1))
            rows.setdefault(r, {})[col_to_idx(ref)] = val

    # Locate EXPENSES section and Total Expenses label
    start = None
    end = None
    for r in sorted(rows):
        a = rows[r].get(1)
        if isinstance(a, str) and a.strip().upper() == "EXPENSES":
            start = r
        if isinstance(a, str) and a.strip().upper() == "TOTAL EXPENSES":
            end = r
    if start is None or end is None or end <= start:
        print(json.dumps({"status": "error", "message": "EXPENSES section not located"}))
        return 1

    items = []
    total = 0.0
    for r in range(start + 1, end):
        amount = rows.get(r, {}).get(3)
        if isinstance(amount, (int, float)) and not isinstance(amount, bool):
            items.append(
                {
                    "row": r,
                    "category": rows[r].get(1),
                    "subcategory": rows[r].get(2),
                    "amount": amount,
                }
            )
            total += amount

    print(
        json.dumps(
            {
                "status": "success",
                "expense_items": items,
                "total_expenses": total,
            },
            indent=2,
        )
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())

